BEGIN
 UPDATE public.game04_redesign_master SET data=jsonb_set(data,'{skills}',old_skills||formal_skills),updated_at=statement_timestamp()
 WHERE key='release_manifest' AND data->'skills'=old_skills;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'MASTER_AUDIT_STOP: skill registry changed or missing; re-read and review'; END IF;
END $audit$;
COMMIT;
